\includegraphics[width=0.49\linewidth]{fig_hp/Truthful_QA_Accuracy.pdf}
\caption{{\DV} showing better performance than GPT-3 on set of Truthful QA questions based on the commonly used text-similarity metrics.}

\end{figure}
